#if AQUANODE_TEST_HARNESS
// 7.0.0 checks (harness mode "round701")
#include <sstream>
std::string aqPhizmOscRound701()
{
    std::ostringstream os;
    auto check = [&os] (bool ok, const juce::String& what) { os << (ok ? "  ok   " : "  FAIL ") << what << "\n"; };
    aqp_phizmosc::TranswaveAudioProcessor p;
    p.prepareToPlay (48000.0, 512);
    juce::String st;
    const int idx = ::twremake::indexOf ("Vowelwave AA");
    check (idx >= 0 && p.loadBuiltinTranswave (0, idx, st) && p.getNumFrames (0) == 131 && p.getSlotOrigin (0) == 3,
           "PhizmOsc: built-in Vowelwave AA in slot A, 131 frames, origin 3 (" + st + ")");
    juce::MemoryBlock mb;
    p.getStateInformation (mb);
    check (mb.getSize() < 20000, "PhizmOsc: its state carries the name, not the audio (" + juce::String ((int) mb.getSize()) + " bytes)");
    aqp_phizmosc::TranswaveAudioProcessor q;
    q.setStateInformation (mb.getData(), (int) mb.getSize());
    check (q.isWavetableLoaded (0) && q.getWavetableName (0) == "Vowelwave AA" && q.getNumFrames (0) == 131 && q.getSlotOrigin (0) == 3,
           "PhizmOsc: the state reopens with the built-in rebuilt");
    bool allOk = aqp_phizmosc::TranswaveAudioProcessor::getNumFactoryPresets() == 5;
    juce::String names;
    for (int i = 0; i < aqp_phizmosc::TranswaveAudioProcessor::getNumFactoryPresets(); ++i)
    {
        aqp_phizmosc::TranswaveAudioProcessor r;
        const bool ok = r.loadFactoryPreset (i) && r.isWavetableLoaded (0) && r.getSlotOrigin (0) == 3;
        allOk = allOk && ok;
        names << aqp_phizmosc::TranswaveAudioProcessor::getFactoryPresetName (i) << " [" << r.getWavetableName (0)
              << (r.isWavetableLoaded (1) ? " + " + r.getWavetableName (1) : juce::String()) << "] ";
    }
    check (allOk, "PhizmOsc factory presets load with built-in tables: " + names);
    return os.str();
}
#endif
